package cli

import (
	"bytes"
	"testing"
)

func TestRunRejectsUnknownFlag(t *testing.T) {
	var stdout, stderr bytes.Buffer
	code := Run([]string{"-no-such-flag"}, &stdout, &stderr)
	if code != exitUsage {
		t.Errorf("Run(-no-such-flag) = %d, want %d", code, exitUsage)
	}
	if stdout.Len() != 0 {
		t.Errorf("Run(-no-such-flag) wrote %q to stdout, want nothing", stdout.String())
	}
}

func TestRunHelpExitsZero(t *testing.T) {
	var stdout, stderr bytes.Buffer
	code := Run([]string{"-h"}, &stdout, &stderr)
	if code != exitOK {
		t.Errorf("Run(-h) = %d, want %d", code, exitOK)
	}
}

func TestRunWithNoArgsExitsZero(t *testing.T) {
	var stdout, stderr bytes.Buffer
	code := Run(nil, &stdout, &stderr)
	if code != exitOK {
		t.Errorf("Run(nil) = %d, want %d", code, exitOK)
	}
}

